import{_ as i,l as s,o as e,c as l,v as r,p as n,x as t,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"DAG 与拓扑序预备","description":"","frontmatter":{"title":"DAG 与拓扑序预备","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dag-repr.md","filePath":"cs/dag-repr.md","lastUpdated":1789023840000}'),h={name:"cs/dag-repr.md"};function A(_,a,m,f,D,u){const o=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="dag-与拓扑序预备" tabindex="-1">DAG 与拓扑序预备 <a class="header-anchor" href="#dag-与拓扑序预备" aria-label="Permalink to &quot;DAG 与拓扑序预备&quot;">​</a></h1><div class="epigraph"><p>有向且无环，顶点就可以排成一条线，使得每条边都从左指向右；有环则不存在这样的序。</p><footer>—— 据 Cormen, Leiserson, Rivest and Stein, Introduction to Algorithms；Kahn, Topological Sorting of Large Networks, CACM 1962 整理</footer></div><p><a href="/cs/csr-graph">上一课</a>把默认图写成稀疏邻接。<a href="/cs/graph-definition">图的定义</a>含有向边。<a href="/cs/tree-as-acyclic">树作为无环连通图</a>的无环是无向的。本课不重讲 CSR。缺口是有向无环图（DAG）作为表示：边表达依赖，且依赖不许成环，从而存在线性扩展——拓扑序。本课只预备「存在性与等价」，真正的 BFS/DFS 算法在算法课程才跑。数据结构课在此结束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>任务 \\(A\\) 必须先于 \\(B\\)，画成 \\(A\\to B\\)。若出现环，没有一种顺序能尊重全部边。缺口不是再选一种邻接格式，而是<strong>把「可线性化的依赖」钉成 DAG 性质</strong>：有向图无环 \\(\\Leftrightarrow\\) 存在拓扑序。表示仍用邻接表；额外不变式是无环。</p><p>入度数组是 Kahn 算法的零件：反复取入度为 0 的点。本课交代序的含义，不把循环不变式写完——那是下一课程第一课。</p><p><span class="marginnote">编译的依赖、Makefile、指令调度的数据依赖，都是 DAG。流水线 RAW 也是依赖边；硬件用转发，软件调度用拓扑。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>检测环：若拓扑过程结束后仍有未输出顶点，则剩下的点都在环里（或由环可达）。表示层可选择拒绝插入成环的边：插入前 <code>find</code> 依赖闭包——那太贵；通常建完再检。</p>',9)),(e(),n(c,null,{default:t(()=>[p(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22A%22%5D%20--%3E%20B%5B%22B%22%5D%0A%20%20A%20--%3E%20C%5B%22C%22%5D%0A%20%20B%20--%3E%20D%5B%22D%22%5D%0A%20%20C%20--%3E%20D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>上图一条拓扑序是 \\(A,B,C,D\\) 或 \\(A,C,B,D\\)。邻接表存储与一般有向图相同；稀疏假设仍然适用。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有了拓扑序，动态规划在 DAG 上按序推才合法：子问题沿边指向已经算完。那是算法课。本课交出对象：稀疏有向无环 + 存在线性扩展。并查集不能代替：它无向且不管方向。</p><p>与调用栈：递归依赖若成环会无限递归；DAG 保证递归依赖可终止——同一无环思想，对象从栈帧换成顶点。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不运行 DFS 打时间戳，不证明白-灰-黑。不引入最短路。权可放在边上，本课不解释松弛。循环不变式课会把「已输出集合」写成归纳断言，那时才算算法开始。</p><p>后课默认：依赖图画成 DAG，邻接表已备好；正确性论证从循环不变式起，不再从「图是什么」起。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DAG = 有向无环；等价于存在拓扑序。</li><li>表示仍是稀疏邻接；无环是额外不变式。</li><li>数据结构课结束；下一课用不变式给循环证明。</li><li>出处：Kahn, <em>CACM</em>, 1962；Cormen et al. 拓扑排序预备。</li></ul>',9))])}const S=i(h,[["render",A]]);export{C as __pageData,S as default};
